// exitFunc is the seam behind usageError's exit. Tests swap it via
// SetExitFunc to intercept the exit; empty means the real os.Exit.
var exitFunc func(int)

// SetExitFunc redirects the exit that UsageError/Run perform — the test
// seam. Pass empty to restore the real os.Exit.
func SetExitFunc(f func(int)) {
	exitFunc = f
}

// exitWithCode runs the exit through the seam.
func exitWithCode(code int) {
	if exitFunc != nil {
		exitFunc(code)
		return
	}
	os.Exit(code)
}

// handlerError wraps an error returned by a fallible action handler so Run
// can tell a runtime failure (print + exit 1) apart from a parse failure
// (usage dump + exit 2). It carries the invoked command's Args so Run can
// inspect IsJSON and format the error accordingly.
type handlerError struct {
	inner error
	args  Args
}

func (e handlerError) Error() string {
	return e.inner.Error()
}

// UsageError renders a usage-style failure the way a user expects from a
// CLI: the reason, then the command's help, to stderr, exiting 2 (the
// conventional usage-error exit code, matching Go's flag package). A user
// typo (unknown flag, arg-vs-flag confusion) prints a readable message —
// not a Go panic with a stack trace.
// Example: cli.UsageError(app, err.Error())
func UsageError(app *Command, reason string) {
	fmt.Fprintf(os.Stderr, "Error: %v\n", reason)
	fmt.Fprintln(os.Stderr, "")
	printHelpTo(os.Stderr, app)
	exitWithCode(2)
}

// Error prints a message to stderr but does not exit and does not affect
// the process exit status — a handler that reports a failure only with
// Error leaves the exit code at 0. To signal a runtime failure, return the
// error from a fallible handler (ActionE) or call Fail.
func Error(msg string) {
	fmt.Fprintln(os.Stderr, msg)
}

// Run parses os.Args and executes the corresponding action. Two failure
// channels, distinguished by exit code: a failed parse prints the reason
// plus help to stderr and exits 2 — the usage-error contract; an error
// returned by a fallible action handler prints `error: <message>` to
// stderr (or `{"error": "<message>"}` to stdout in JSON mode) and exits 1
// — the runtime-failure contract. Neither dumps a Go panic. Programs that
// want custom handling or a testable seam call RunWithArgs, which returns both
// kinds of error.
func Run(app *Command) {
	err := RunWithArgs(app, os.Args)
	if he, _isOk := err.(handlerError); _isOk {
		if IsJSON(he.args) {
			PrintJSON(map[string]any{"error": fmt.Sprintf("%v", he.inner)})
		} else {
			fmt.Fprintf(os.Stderr, "error: %v\n", he.inner)
		}
		exitWithCode(1)
		return
	}
	if err != nil {
		UsageError(app, fmt.Sprintf("%v", err))
	}
}

// ParseResult classifies what a parsed invocation wants to do.
// Execute carries the resolved handler plus populated Args — the plain
// Handler for Action handlers, HandlerE for fallible ActionE handlers.
// ShowHelp carries the deepest resolved command (empty for root help) and
// the command-path tokens to display. Invalid carries the reason parsing
// failed.
type ParseResult interface{ isParseResult() }

type Execute struct {
	Handler  func(Args)
	HandlerE func(Args) error
	Args     Args
}

func (Execute) isParseResult() {}

type ShowHelp struct {
	Cmd  *Command
	Path []string
	Root bool
}

func (ShowHelp) isParseResult() {}

type ShowVersion struct{}

func (ShowVersion) isParseResult() {}

type Invalid struct {
	Reason string
}

func (Invalid) isParseResult() {}

// Parse classifies an argv slice (including the program name at index 0)
// without executing anything. This is the pure core of Run: help requests,
// version requests, dispatch targets, validation failures, and root
// fallbacks all come back as explicit outcomes.
func Parse(app *Command, args []string) ParseResult {
	if len(args) < 2 {
		values := defaultValues(app, nil)
		rootArgs := Args{values: values, rest: map[string][]string{}}
		for _, f := range app.Flags {
			if f.Required && values[f.Name] == "" {
				return Invalid{Reason: fmt.Sprintf("flag --%v is required", f.Name)}
			}
		}
		for _, a := range app.Args {
			if a.Required && values[a.Name] == "" {
				return Invalid{Reason: fmt.Sprintf("argument %v is required", a.Name)}
			}
		}
		if app.ActionFuncE != nil {
			return Execute{Handler: nil, HandlerE: app.ActionFuncE, Args: rootArgs}
		}
		if app.ActionFunc != nil {
			return Execute{Handler: app.ActionFunc, Args: rootArgs}
		}
		if app.DefaultActionE != nil {
			return Execute{Handler: nil, HandlerE: app.DefaultActionE, Args: rootArgs}
		}
		if app.DefaultAction != nil {
			return Execute{Handler: app.DefaultAction, Args: rootArgs}
		}
		return ShowHelp{Cmd: app, Path: []string{}, Root: true}
	}
	subIndex := skipGlobalFlags(app, args, 1)
	if subIndex < len(args) {
		sub := args[subIndex]
		if sub == "--version" || sub == "-v" {
			return ShowVersion{}
		}
		if sub == "help" || sub == "-h" || sub == "--help" {
			helpLeaf, helpLeafArgStart := findLeaf(app, args, subIndex+1)
			if helpLeaf != nil {
				return ShowHelp{Cmd: helpLeaf, Path: args[subIndex+1 : helpLeafArgStart], Root: false}
			}
			return ShowHelp{Cmd: app, Path: []string{}, Root: true}
		}
		leaf, leafArgStart := findLeaf(app, args, subIndex)
		if leaf != nil {
			return parseLeaf(app, leaf, args, 1, subIndex, leafArgStart)
		}
	}
	rootActionE := app.DefaultActionE
	rootAction := app.DefaultAction
	if (rootActionE == nil) && (rootAction == nil) {
		rootActionE = app.ActionFuncE
		rootAction = app.ActionFunc
	}
	values := defaultValues(app, nil)
	positionalNames := []string{}
	for _, a := range app.Args {
		positionalNames = append(positionalNames, a.Name)
	}
	allFlagDefs := []FlagDef{}
	allFlagDefs = append(allFlagDefs, app.GlobalFlags...)
	allFlagDefs = append(allFlagDefs, app.Flags...)
	restMap := map[string][]string{}
	rootUnknown := parseFlagsAndPositionals(args, 1, values, restMap, positionalNames, allFlagDefs, app.RestArgName)
	if len(rootUnknown) != 0 {
		return Invalid{Reason: fmt.Sprintf("unknown flag: --%v", rootUnknown[0])}
	}
	if bad := validateTypedValues(values, allFlagDefs); bad != "" {
		return Invalid{Reason: fmt.Sprintf("flag --%v has an invalid value", bad)}
	}
	for _, f := range app.Flags {
		if f.Required && values[f.Name] == "" {
			return Invalid{Reason: fmt.Sprintf("flag --%v is required", f.Name)}
		}
	}
	for _, a := range app.Args {
		if a.Required && values[a.Name] == "" {
			return Invalid{Reason: fmt.Sprintf("argument %v is required", a.Name)}
		}
	}
	if rootActionE != nil {
		return Execute{Handler: nil, HandlerE: rootActionE, Args: Args{values: values, rest: restMap}}
	}
	if rootAction != nil {
		return Execute{Handler: rootAction, Args: Args{values: values, rest: restMap}}
	}
	return ShowHelp{Cmd: app, Path: []string{}, Root: true}
}

// RunWithArgs parses the given args slice and executes the corresponding action.
// Useful for testing CLI dispatch without modifying os.Args. Returns a
// failed parse's reason bare, or a fallible handler's error wrapped so Run
// can distinguish the runtime-failure exit (1) from the usage-error exit
// (2) — the message is the handler's either way. A plain Action handler's
// outcome is not propagated.
func RunWithArgs(app *Command, args []string) error {
	outcome := Parse(app, args)
	switch oc := outcome.(type) {
	case Execute:
		if oc.HandlerE != nil {
			herr := oc.HandlerE(oc.Args)
			if herr != nil {
				return handlerError{inner: herr, args: oc.Args}
			}
			return nil
		}
		oc.Handler(oc.Args)
		return nil
	case ShowHelp:
		if oc.Root {
			printHelp(app)
		} else {
			printLeafHelp(app, oc.Cmd, oc.Path)
		}
		return nil
	case ShowVersion:
		if app.Version != "" {
			fmt.Printf("%v %v\n", app.Name, app.Version)
		} else {
			fmt.Println(app.Name)
		}
		return nil
	case Invalid:
		return errors.New(oc.Reason)
	}
	return nil
}

// defaultValues returns a fresh map seeded with global and (optionally) leaf defaults.
func defaultValues(app *Command, leaf *Command) map[string]string {
	values := map[string]string{}
	for _, f := range app.GlobalFlags {
		values[f.Name] = f.DefaultValue
	}
	if leaf == nil {
		for _, f := range app.Flags {
			values[f.Name] = f.DefaultValue
		}
	} else {
		for _, f := range leaf.Flags {
			values[f.Name] = f.DefaultValue
		}
	}
	return values
}

// parseFlagsAndPositionals walks args[start:] populating values with parsed flags
// and positional arguments. flagDefs is used to build alias and kind maps so
// that bool flags never swallow positionals, typed flags consume unconditionally,
// and alias names resolve to canonical flag names. Overflow positionals are
// written to rest[restArgName] when restArgName is non-empty.
//
// Returns the list of unknown flag names encountered (flags not present in
// flagDefs or their aliases). Callers that want to reject typos should error
// on a non-empty return; ParseArgs ignores it for test compatibility.
func parseFlagsAndPositionals(args []string, start int, values map[string]string, rest map[string][]string, positionalNames []string, flagDefs []FlagDef, restArgName string) []string {
	aliasMap := map[string]string{}
	kindMap := map[string]FlagKind{}
	known := map[string]bool{}
	for _, f := range flagDefs {
		known[f.Name] = true
		kindMap[f.Name] = f.Kind
		for _, a := range f.Aliases {
			aliasMap[a] = f.Name
			known[a] = true
		}
	}
	unknown := []string{}
	posIndex := 0
	i := start
	for i < len(args) {
		arg := args[i]
		if kukistring.HasPrefix(arg, "-") && kukistring.Contains(arg, "=") {
			parts := kukistring.SplitN(arg, "=", 2)
			rawName := kukistring.TrimPrefix(parts[0], "--")
			rawName = kukistring.TrimPrefix(rawName, "-")
			canonical := kukistring.Or(aliasMap[rawName], rawName)
			if !known[canonical] {
				unknown = append(unknown, canonical)
			}
			values[canonical] = parts[1]
			i += 1
		} else if kukistring.HasPrefix(arg, "--") {
			name := kukistring.TrimPrefix(arg, "--")
			canonical := kukistring.Or(aliasMap[name], name)
			if !known[canonical] {
				unknown = append(unknown, canonical)
			}
			if kindMap[canonical] == FlagKindBool {
				values[canonical] = "true"
				i += 1
			} else if kindMap[canonical] != FlagKindString && i+1 < len(args) {
				values[canonical] = args[i+1]
				i += 2
			} else if kindMap[canonical] != FlagKindString {
				i += 1
			} else if i+1 < len(args) && !kukistring.HasPrefix(args[i+1], "-") {
				values[canonical] = args[i+1]
				i += 2
			} else {
				values[canonical] = "true"
				i += 1
			}
		} else if kukistring.HasPrefix(arg, "-") {
			name := kukistring.TrimPrefix(arg, "-")
			canonical := kukistring.Or(aliasMap[name], name)
			if !known[canonical] {
				unknown = append(unknown, canonical)
			}
			if kindMap[canonical] == FlagKindBool {
				values[canonical] = "true"
				i += 1
			} else if kindMap[canonical] != FlagKindString && i+1 < len(args) {
				values[canonical] = args[i+1]
				i += 2
			} else if kindMap[canonical] != FlagKindString {
				i += 1
			} else if i+1 < len(args) && !kukistring.HasPrefix(args[i+1], "-") {
				values[canonical] = args[i+1]
				i += 2
			} else {
				values[canonical] = "true"
				i += 1
			}
		} else {
			if posIndex < len(positionalNames) {
				values[positionalNames[posIndex]] = arg
				posIndex += 1
			} else if restArgName != "" {
				rest[restArgName] = append(rest[restArgName], arg)
			}
			i += 1
		}
	}
	return unknown
}

// validateTypedValues checks that bool and int flag values in `values` are
// well-formed. Returns the name of the first malformed flag, or "" when all
// typed values parse cleanly. Unknown flags (not in flagDefs) are skipped —
// the caller already rejects those separately.
func validateTypedValues(values map[string]string, flagDefs []FlagDef) string {
	for _, f := range flagDefs {
		v := values[f.Name]
		if v == "" {
			continue
		}
		if f.Kind == FlagKindBool {
			lower := kukistring.ToLower(v)
			if lower == "true" || lower == "false" || lower == "1" || lower == "0" || lower == "yes" || lower == "no" || lower == "on" || lower == "off" {
				continue
			}
			return f.Name
		}
		if f.Kind == FlagKindInt {
			_, err := parse.Int(v)
			if err != nil {
				return f.Name
			}
		}
	}
	return ""
}

// parseLeaf parses arguments for a matched leaf subcommand and classifies the
// result. leadingStart is where leading global flags may begin (always 1 — the
// token after the program name). subIndex is where the subcommand token sits
// (after any leading global flags). leafArgStart is the index of the first
// non-subcommand token after the leaf path.
func parseLeaf(app *Command, leaf *Command, args []string, leadingStart int, subIndex int, leafArgStart int) ParseResult {
	{
		_iStart, _iEnd := leafArgStart, len(args)
		_iStep := _iStart + 1 - _iStart
		if _iStart > _iEnd {
			_iStep = -_iStep
		}
		for i := _iStart; i != _iEnd; i += _iStep {
			a := args[i]
			if a == "--help" || a == "-h" {
				return ShowHelp{Cmd: leaf, Path: args[subIndex:leafArgStart], Root: false}
			}
		}
	}
	values := defaultValues(app, leaf)
	if subIndex > leadingStart {
		headSlice := []string{}
		headSlice = append(headSlice, args[0])
		headSlice = append(headSlice, args[leadingStart:subIndex]...)
		globalFlagDefs := []FlagDef{}
		globalFlagDefs = append(globalFlagDefs, app.GlobalFlags...)
		emptyRestMap := map[string][]string{}
		leadingUnknown := parseFlagsAndPositionals(headSlice, 1, values, emptyRestMap, []string{}, globalFlagDefs, "")
		if len(leadingUnknown) != 0 {
			return Invalid{Reason: fmt.Sprintf("unknown flag: --%v", leadingUnknown[0])}
		}
	}
	positionalNames := make([]string, 0)
	for _, a := range leaf.Args {
		positionalNames = append(positionalNames, a.Name)
	}
	allFlagDefs := []FlagDef{}
	allFlagDefs = append(allFlagDefs, app.GlobalFlags...)
	allFlagDefs = append(allFlagDefs, leaf.Flags...)
	restMap := map[string][]string{}
	trailingUnknown := parseFlagsAndPositionals(args, leafArgStart, values, restMap, positionalNames, allFlagDefs, leaf.RestArgName)
	if len(trailingUnknown) != 0 {
		return Invalid{Reason: fmt.Sprintf("unknown flag: --%v", trailingUnknown[0])}
	}
	if bad := validateTypedValues(values, allFlagDefs); bad != "" {
		return Invalid{Reason: fmt.Sprintf("flag --%v has an invalid value", bad)}
	}
	for _, f := range leaf.Flags {
		if f.Required && values[f.Name] == "" {
			return Invalid{Reason: fmt.Sprintf("flag --%v is required", f.Name)}
		}
	}
	for _, a := range leaf.Args {
		if a.Required && values[a.Name] == "" {
			return Invalid{Reason: fmt.Sprintf("argument %v is required", a.Name)}
		}
	}
	if leaf.ActionFuncE != nil {
		return Execute{Handler: nil, HandlerE: leaf.ActionFuncE, Args: Args{values: values, rest: restMap}}
	}
	if leaf.ActionFunc == nil {
		return Invalid{Reason: fmt.Sprintf("no action defined for command %v", leaf.Name)}
	}
	return Execute{Handler: leaf.ActionFunc, Args: Args{values: values, rest: restMap}}
}

// findLeaf returns the deepest matching subcommand for args starting at
// subIndex, and the index of the first non-subcommand token after the leaf
// path. Returns empty if no top-level match.
func findLeaf(app *Command, args []string, subIndex int) (*Command, int) {
	if subIndex >= len(args) {
		return nil, 0
	}
	subName := args[subIndex]
	for _, s := range app.Subcommands {
		if s.Name == subName {
			return matchNested(s, args, subIndex+1)
		}
	}
	return nil, 0
}

func matchNested(cmd *Command, args []string, index int) (*Command, int) {
	if index >= len(args) {
		return cmd, index
	}
	nextSub := args[index]
	for _, s := range cmd.Subcommands {
		if s.Name == nextSub {
			return matchNested(s, args, index+1)
		}
	}
	return cmd, index
}

// skipGlobalFlags returns the index of the first token in args[start:] that
// is not a leading global flag. It inspects app.GlobalFlags to decide whether
// each flag token consumes the next arg (string/int) or not (bool). Unknown
// flags (not in GlobalFlags) stop the scan so the rest of the args are
// resolved as a subcommand or positionals. Handles --name=value and
// -k=value forms without advancing past the value token.
func skipGlobalFlags(app *Command, args []string, start int) int {
	if len(app.GlobalFlags) == 0 {
		return start
	}
	byName := map[string]FlagDef{}
	byAlias := map[string]FlagDef{}
	for _, f := range app.GlobalFlags {
		byName[f.Name] = f
		for _, a := range f.Aliases {
			byAlias[a] = f
		}
	}
	i := start
	for i < len(args) {
		arg := args[i]
		if !kukistring.HasPrefix(arg, "-") {
			return i
		}
		if kukistring.Contains(arg, "=") {
			i += 1
			continue
		}
		name := kukistring.TrimPrefix(arg, "--")
		name = kukistring.TrimPrefix(name, "-")
		def, ok := lookupGlobal(byName, byAlias, name)
		if !ok {
			return i
		}
		if def.Kind == FlagKindBool {
			i += 1
		} else if i+1 < len(args) {
			i += 2
		} else {
			i += 1
		}
	}
	return i
}

// lookupGlobal checks the byName and byAlias maps and returns (def, true) on hit.
func lookupGlobal(byName map[string]FlagDef, byAlias map[string]FlagDef, name string) (FlagDef, bool) {
	def, ok := byName[name]
	if ok {
		return def, true
	}
	def, ok = byAlias[name]
	if ok {
		return def, true
	}
	return FlagDef{}, false
}

// printHelp renders styled help to stdout. Colors apply when stdout is a tty
// and not suppressed by NO_COLOR; otherwise the output is plain text.
func printHelp(app *Command) {
	printHelpTo(os.Stdout, app)
}

// printHelpTo renders the root help to an explicit destination — stdout for
// help requests, stderr for usage errors.
func printHelpTo(w *os.File, app *Command) {
	s := color.NewStyler(w)
	out := func(line string) {
		fmt.Fprintln(w, line)
	}
	usageLabel := s.Bold("Usage:")
	nameStyled := s.Cyan(app.Name)
	out(fmt.Sprintf("%v %v [flags] [subcommand]", usageLabel, nameStyled))
	if app.Description != "" {
		out("")
		out(app.Description)
	}
	if len(app.GlobalFlags) != 0 || len(app.Flags) != 0 {
		out("")
		out(s.Bold("Flags:"))
		nameWidth := flagNameWidth(app)
		for _, f := range app.GlobalFlags {
			printFlagRowTo(w, s, f, nameWidth)
		}
		for _, f := range app.Flags {
			printFlagRowTo(w, s, f, nameWidth)
		}
	}
	if len(app.Subcommands) != 0 {
		out("")
		out(s.Bold("Subcommands:"))
		nameWidth := subcommandNameWidth(app)
		for _, sub := range app.Subcommands {
			padded := padRight(sub.Name, nameWidth)
			out(fmt.Sprintf("  %v  %v", s.Cyan(padded), s.Dim(sub.Description)))
		}
	}
	if app.Version != "" {
		out("")
		versionLabel := s.Dim("Version:")
		out(fmt.Sprintf("%v %v", versionLabel, app.Version))
	}
}

// printLeafHelp renders help for a specific subcommand, including its flags,
// positional arguments, and nested subcommands (if any). `path` is the
// subcommand path from the program name, e.g. ["dep", "add"].
func printLeafHelp(app *Command, leaf *Command, path []string) {
	s := color.NewStyler(os.Stdout)
	usageLabel := s.Bold("Usage:")
	nameStyled := s.Cyan(app.Name)
	pathStyled := ""
	for _, p := range path {
		pathStyled = pathStyled + " " + s.Cyan(p)
	}
	if len(leaf.Subcommands) != 0 {
		fmt.Printf("%v %v%v [subcommand] [flags]\n", usageLabel, nameStyled, pathStyled)
	} else {
		fmt.Printf("%v %v%v [flags]\n", usageLabel, nameStyled, pathStyled)
	}
	if leaf.Description != "" {
		fmt.Println("")
		fmt.Println(leaf.Description)
	}
	if len(leaf.Args) != 0 {
		fmt.Println("")
		fmt.Println(s.Bold("Arguments:"))
		argWidth := leafArgNameWidth(leaf)
		for _, a := range leaf.Args {
			padded := padRight(a.Name, argWidth)
			suffix := ""
			if a.Required {
				suffix = " (required)"
			}
			fmt.Printf("  %v  %v\n", s.Cyan(padded), s.Dim(a.Description+suffix))
		}
	}
	if len(app.GlobalFlags) != 0 || len(leaf.Flags) != 0 {
		fmt.Println("")
		fmt.Println(s.Bold("Flags:"))
		nameWidth := leafFlagNameWidth(app, leaf)
		for _, f := range app.GlobalFlags {
			printFlagRow(s, f, nameWidth)
		}
		for _, f := range leaf.Flags {
			printFlagRow(s, f, nameWidth)
		}
	}
	if len(leaf.Subcommands) != 0 {
		fmt.Println("")
		fmt.Println(s.Bold("Subcommands:"))
		nameWidth := subcommandListNameWidth(leaf.Subcommands)
		for _, sub := range leaf.Subcommands {
			padded := padRight(sub.Name, nameWidth)
			fmt.Printf("  %v  %v\n", s.Cyan(padded), s.Dim(sub.Description))
		}
	}
}

// leafFlagNameWidth returns the longest flag name (with "--" prefix) across
// global flags and the leaf's own flags, capped at 24.
func leafFlagNameWidth(app *Command, leaf *Command) int {
	max := 0
	for _, f := range app.GlobalFlags {
		n := len(fmt.Sprintf("--%v", f.Name))
		if n > max {
			max = n
		}
	}
	for _, f := range leaf.Flags {
		n := len(fmt.Sprintf("--%v", f.Name))
		if n > max {
			max = n
		}
	}
	if max > 24 {
		return 24
	}
	return max
}

// leafArgNameWidth returns the longest positional arg name, capped at 20.
func leafArgNameWidth(leaf *Command) int {
	max := 0
	for _, a := range leaf.Args {
		if len(a.Name) > max {
			max = len(a.Name)
		}
	}
	if max > 20 {
		return 20
	}
	return max
}

// printFlagRow renders one flag row. "--name" is highlighted in cyan,
// the description is dimmed, default value (if any) shown in parentheses.
func printFlagRow(s color.Styler, f FlagDef, width int) {
	printFlagRowTo(os.Stdout, s, f, width)
}

// printFlagRowTo renders one flag line to an explicit destination.
func printFlagRowTo(w *os.File, s color.Styler, f FlagDef, width int) {
	flagName := fmt.Sprintf("--%v", f.Name)
	padded := padRight(flagName, width)
	suffix := ""
	if f.Required {
		suffix = " (required)"
	} else if f.DefaultValue != "" && f.DefaultValue != "false" {
		suffix = fmt.Sprintf(" (default: %v)", f.DefaultValue)
	}
	fmt.Fprintf(w, "  %v  %v\n", s.Cyan(padded), s.Dim(f.Description+suffix))
}

// flagNameWidth returns the longest flag name (with "--" prefix) across the
// app, so descriptions line up. Capped at 24 to keep wide flag names from
// pushing all descriptions off-screen.
func flagNameWidth(app *Command) int {
	max := 0
	for _, f := range app.GlobalFlags {
		n := len(fmt.Sprintf("--%v", f.Name))
		if n > max {
			max = n
		}
	}
	for _, f := range app.Flags {
		n := len(fmt.Sprintf("--%v", f.Name))
		if n > max {
			max = n
		}
	}
	if max > 24 {
		return 24
	}
	return max
}

// subcommandNameWidth returns the longest subcommand name, capped at 20.
func subcommandNameWidth(app *Command) int {
	return subcommandListNameWidth(app.Subcommands)
}

// subcommandListNameWidth returns the longest name across a list of
// subcommands, capped at 20.
func subcommandListNameWidth(subs []*Command) int {
	max := 0
	for _, sub := range subs {
		if len(sub.Name) > max {
			max = len(sub.Name)
		}
	}
	if max > 20 {
		return 20
	}
	return max
}

// padRight returns s padded with spaces on the right to at least n columns.
// Returns s unchanged if it's already that wide.
func padRight(text string, n int) string {
	if len(text) >= n {
		return text
	}
	pad := n - len(text)
	return text + kukistring.Repeat(" ", pad)
}

// IsJSON reports whether the caller requested JSON output (agentic mode).
func IsJSON(args Args) bool {
	val := args.values["json"]
	if val == "true" || val == "1" || val == "yes" {
		return true
	}
	val = args.values["output"]
	return val == "json"
}

// Context returns a context that is cancelled when the CLI receives an
// interrupt (SIGINT) or SIGTERM signal. Use this to wire
// graceful shutdown into long-running CLI actions.
func (args Args) Context() context.Context {
	ctx, _ := signal.Context(signal.SignalInterrupt, signal.SignalTerminate)
	return ctx
}

// Respond outputs data in a format suitable for the caller.
func (args Args) Respond(data any) {
	if IsJSON(args) {
		err_1 := json.WriteOutput(data)
		if err_1 != nil {
			Fatal(fmt.Sprintf("failed to encode json: %v", err_1))
			return
		}
	} else {
		fmt.Println(fmt.Sprint(data))
	}
}

// PrintJSON encodes v with indented formatting (json.PrettyBytes) and writes it to stdout.
// If serialization fails, the error is written to stderr.
// Example: cli.PrintJSON(result)
func PrintJSON(v any) {
	data, err_2 := json.PrettyBytes(v)
	if err_2 != nil {
		Error(fmt.Sprintf("json error: %v", err_2))
		return
	}
	fmt.Println(string(data))
}

// RespondPretty outputs data indented as JSON in agentic mode (when IsJSON(args) is true),
// or formats it using default string display otherwise.
// Example: args.RespondPretty(result)
func (args Args) RespondPretty(data any) {
	if IsJSON(args) {
		PrintJSON(data)
	} else {
		fmt.Println(fmt.Sprint(data))
	}
}

// IsTTY reports whether the standard output is a terminal.
func IsTTY() bool {
	return term.IsTTY(os.Stdout)
}

// Info prints a diagnostic message to stderr.
func Info(msg string) {
	fmt.Fprintln(os.Stderr, msg)
}

// Success prints a diagnostic message to stderr.
func Success(msg string) {
	fmt.Fprintln(os.Stderr, msg)
}

// Fatal prints a message to stderr and exits with code 1. The exit goes
// through the SetExitFunc seam so tests can intercept it. Exiting
// immediately skips deferred cleanup — prefer reporting failures from a
// fallible ActionE handler, which lets defers run before Run exits.
func Fatal(msg string) {
	fmt.Fprintln(os.Stderr, msg)
	exitWithCode(1)
}

// Fail prints a message to stderr and exits with code 1 through the
// SetExitFunc seam — the seam-aware twin of Fatal for handlers that cannot
// return a fallible error. Exiting immediately skips deferred cleanup;
// prefer ActionE when the handler can return an error instead.
// Example: cli.Fail("db open failed")
func Fail(msg string) {
	fmt.Fprintln(os.Stderr, msg)
	exitWithCode(1)
}

// FailArgs reports a command failure and exits with code 1.
// In JSON mode (when IsJSON(args) is true), it writes `{"error": msg}` as JSON
// to stdout so autonomous agents receive a well-formed JSON response on stdout.
// Otherwise, it writes a red error message to stderr.
// Exits with code 1 via the testable SetExitFunc seam.
// Example: cli.FailArgs(args, "cannot open database: {error}")
func FailArgs(args Args, msg string) {
	if IsJSON(args) {
		PrintJSON(map[string]any{"error": msg})
	} else {
		fmt.Fprintf(os.Stderr, "%v %v\n", color.Red("error:"), msg)
	}
	exitWithCode(1)
}

// Fail reports a command failure and exits with code 1.
// Receiver form of FailArgs for pipe or method syntax.
// Example: args.Fail("cannot open database: {error}")
func (args Args) Fail(msg string) {
	FailArgs(args, msg)
}

// ExitCode terminates the process with the given status through the
// SetExitFunc seam, so tests can intercept the exit. Exiting immediately
// skips deferred cleanup; prefer ActionE when the handler can return an
// error instead.
// Example: cli.ExitCode(3)
func ExitCode(code int) {
	exitWithCode(code)
}

// GetString returns the value of a named argument or flag
func GetString(args Args, name string) string {
	return args.values[name]
}

// GetStringOr returns the value of a named argument or flag, or defaultVal if absent.
func GetStringOr(args Args, name string, defaultVal string) string {
	val := args.values[name]
	if val == "" {
		return defaultVal
	}
	return val
}

// GetBool returns the boolean value of a flag
func GetBool(args Args, name string) bool {
	val := args.values[name]
	return val == "true" || val == "1" || val == "yes"
}

// GetBoolOr returns the boolean value of a flag, or defaultVal if absent or invalid.
// Example: debug := cli.GetBoolOr(args, "verbose", false)
func GetBoolOr(args Args, name string, defaultVal bool) bool {
	val := args.values[name]
	if val == "" {
		return defaultVal
	}
	lower := kukistring.ToLower(val)
	if lower == "true" || lower == "1" || lower == "yes" || lower == "on" {
		return true
	}
	if lower == "false" || lower == "0" || lower == "no" || lower == "off" {
		return false
	}
	return defaultVal
}

// GetInt returns the integer value of an argument
func GetInt(args Args, name string) (int, error) {
	strVal := args.values[name]
	if strVal == "" {
		return 0, fmt.Errorf("argument %v not found", name)
	}
	return parse.Int(strVal)
}

// GetIntOr returns the integer value of an argument, or defaultVal if absent or invalid.
// Example: port := cli.GetIntOr(args, "limit", 10)
func GetIntOr(args Args, name string, defaultVal int) int {
	strVal := args.values[name]
	if strVal == "" {
		return defaultVal
	}
	n, err := parse.Int(strVal)
	if err != nil {
		return defaultVal
	}
	return n
}

// GetFloat returns the float64 value of an argument
// Returns an error if not found or not a valid float
// Example: rate := cli.GetFloat(args, "rate") onerr return
func GetFloat(args Args, name string) (float64, error) {
	strVal := args.values[name]
	if strVal == "" {
		return 0.0, fmt.Errorf("argument %v not found", name)
	}
	return parse.Float64(strVal)
}

// GetFloatOr returns the float64 value of an argument, or defaultVal if absent or invalid.
// Example: rate := cli.GetFloatOr(args, "rate", 1.0)
func GetFloatOr(args Args, name string, defaultVal float64) float64 {
	strVal := args.values[name]
	if strVal == "" {
		return defaultVal
	}
	n, err := parse.Float64(strVal)
	if err != nil {
		return defaultVal
	}
	return n
}

// GetRest returns the list of variadic positional values collected under a
// rest arg name declared with RestArg. Returns an empty list when none.
func GetRest(args Args, name string) []string {
	vals := args.rest[name]
	if vals == nil {
		return []string{}
	}
	return vals
}

// ParseArgs parses an explicit args slice against an app definition and
// returns the populated Args. Useful for unit-testing CLI handlers without
// going through os.Args.
// Example: args := cli.ParseArgs(app, list of string{"myapp", "--verbose", "file.txt"})
func ParseArgs(app *Command, osArgs []string) Args {
	values := map[string]string{}
	for _, f := range app.GlobalFlags {
		values[f.Name] = f.DefaultValue
	}
	for _, f := range app.Flags {
		values[f.Name] = f.DefaultValue
	}
	positionalNames := []string{}
	for _, a := range app.Args {
		positionalNames = append(positionalNames, a.Name)
	}
	allFlagDefs := []FlagDef{}
	allFlagDefs = append(allFlagDefs, app.GlobalFlags...)
	allFlagDefs = append(allFlagDefs, app.Flags...)
	restMap := map[string][]string{}
	start := func() int {
		if len(osArgs) != 0 {
			return 1
		} else {
			return 0
		}
	}()
	parseFlagsAndPositionals(osArgs, start, values, restMap, positionalNames, allFlagDefs, app.RestArgName)
	return Args{values: values, rest: restMap}
}
